[43.2063017,-9.0331423],[43.2060625,-9.0330768],[43.2059027,-9.0331445],[43.2053733,-9.033219],[43.2050852,-9.033289],[43.2048124,-9.0334148],[43.2046994,-9.0334262],[43.2045107,-9.0334713],[43.2044057,-9.0335177],[43.2043759,-9.0334942],[43.2042666,-9.0335383],[43.2042113,-9.0335985],[43.2040926,-9.0336575],[43.203958,-9.0337014],[43.2039531,-9.0336922],[43.2038116,-9.0337271],[43.2034063,-9.0337618],[43.2031852,-9.0337525],[43.2025837,-9.0338208],[43.2024249,-9.0338597],[43.2022388,-9.0339405],[43.2020798,-9.0339861],[43.2019089,-9.0339747],[43.2017398,-9.0339059],[43.2014186,-9.0336367],[43.201312,-9.0336632],[43.2011899,-9.0338198],[43.2010721,-9.0339554],[43.2009231,-9.0340888],[43.2008101,-9.0341654],[43.2005653,-9.0343514],[43.2004607,-9.0346417],[43.2004565,-9.0346866],[43.2003786,-9.0348313],[43.2003826,-9.0348283],[43.2002584,-9.034871],[43.1999596,-9.0348528],[43.1999377,-9.0348583],[43.199788,-9.0348127],[43.1995615,-9.0346623],[43.1992988,-9.0346275],[43.1992706,-9.0346326],[43.1991676,-9.0345802],[43.1988291,-9.0345063],[43.1986502,-9.0345282],[43.1985496,-9.0345815],[43.1984801,-9.0346006],[43.1982407,-9.0346382],[43.1979746,-9.034609],[43.1978015,-9.0345205],[43.1976099,-9.0343765],[43.1975297,-9.0342642],[43.1974628,-9.0342182],[43.1972464,-9.0341143],[43.1971725,-9.0340171],[43.1971227,-9.0339889],[43.1970045,-9.0338867],[43.1967901,-9.0337588],[43.1966154,-9.0336751],[43.1964877,-9.0335809],[43.1964272,-9.033565],[43.196303,-9.0335041],[43.1961988,-9.033428],[43.1961378,-9.033402],[43.1960703,-9.033316],[43.1960419,-9.0333209],[43.1959169,-9.0333145],[43.1958666,-9.033363],[43.1958233,-9.0333608],[43.1956222,-9.0335125],[43.1955719,-9.0335148],[43.1954235,-9.0336674],[43.1954042,-9.0338887],[43.1953732,-9.0340746],[43.1952773,-9.0342699],[43.1951488,-9.0347015],[43.1950475,-9.0348171],[43.194904,-9.0350157],[43.194814,-9.0351946],[43.1947392,-9.0352955],[43.1945362,-9.035678],[43.1945371,-9.0358308],[43.1945521,-9.0359583],[43.1945158,-9.0363538],[43.1944521,-9.0366363],[43.1944137,-9.0369229],[43.1943654,-9.0374589],[43.1943342,-9.03769],[43.1943319,-9.0378862],[43.1943384,-9.0380669],[43.1943084,-9.0382494],[43.1942645,-9.0383048],[43.1940524,-9.0383026],[43.1939679,-9.0384632],[43.1939693,-9.0385148],[43.1939289,-9.0387094],[43.1938942,-9.0387208],[43.1938948,-9.0387861],[43.1938494,-9.0389706],[43.1938251,-9.0391247],[43.1937884,-9.0392479],[43.1936813,-9.0394021],[43.193689,-9.0396058],[43.1936997,-9.0396425],[43.1935953,-9.0397741],[43.1933331,-9.0399474],[43.193312,-9.0399694],[43.1932672,-9.0399644],[43.1928561,-9.040163],[43.1926816,-9.0402616],[43.1924751,-9.0404078],[43.1922961,-9.0405214],[43.1920138,-9.0407238],[43.1919903,-9.0407551],[43.1919962,-9.0407422],[43.1917357,-9.0408934],[43.1915206,-9.041103],[43.1913099,-9.0412084],[43.1910819,-9.0413809],[43.1909115,-9.0415301],[43.1907781,-9.0416124],[43.1905312,-9.0417097],[43.1904743,-9.0417211],[43.1901406,-9.0420949],[43.189898,-9.04246],[43.1897347,-9.0425913],[43.1895698,-9.0426338],[43.1894365,-9.0426784],[43.1892712,-9.0426942],[43.188926,-9.0427594],[43.1883968,-9.0427941]]}]$items$::jsonb;
  v_item jsonb;
  v_coords jsonb;
  v_route record;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_loop_gap_km double precision;
  v_invalid integer;
  v_points jsonb;
begin
  for v_item in select value from jsonb_array_elements(v_items)
  loop
    v_coords := v_item->'coords';

    select h.id,h.latitude,h.longitude,h.distance_km,t.status
      into v_route
      from public.hiking_routes h
      join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_item->>'id'
        and h.source='openstreetmap'
        and h.name=v_item->>'name'
        and h.route_ref=v_item->>'ref'
        and h.official_url=v_item->>'official'
        and exists (
          select 1 from public.hiking_route_regions r
          where r.route_id=h.id and r.published
        );

    if not found then
      raise exception 'Galicia route identity or published region changed: %',v_item->>'id';
    end if;
    if v_route.status='ready' then
      continue;
    end if;
    if v_route.status<>'missing' then
      raise exception 'Galicia route status changed for %: %',v_route.id,v_route.status;
    end if;

    with points as (
      select ordinality idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
    ), steps as (
      select *,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon
      from points
    ), distances as (
      select case when prev_lat is null then 0 else
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid
      from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;

    select ST_DistanceSphere(
      ST_MakePoint((v_coords->0->>1)::double precision,
        (v_coords->0->>0)::double precision),
      ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
        (v_coords->(v_count-1)->>0)::double precision))/1000
      into v_loop_gap_km;

    if v_count<>(v_item->>'pts')::integer
      or v_invalid>0
      or abs(v_length_km-(v_item->>'len')::double precision)>0.03
      or v_max_gap_km>0.10
      or v_center_gap_km>(v_item->>'center')::double precision
      or (
        v_item->>'type'='Circular'
        and v_loop_gap_km>(v_item->>'loop')::double precision
      ) then
      raise exception 'Galicia track validation failed for %: points %, length %, gap %, center %, loop %, invalid %',
        v_route.id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_loop_gap_km,v_invalid;
    end if;

    select jsonb_agg(jsonb_build_object(
      'lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision
    ) order by ordinality)
      into v_points
      from jsonb_array_elements(v_coords)
        with ordinality as p(point,ordinality);

    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (
      v_route.id,'ready',jsonb_build_array(v_points),now(),true,
      'Turismo de Galicia (Xunta de Galicia) - KML oficial',
      v_item->>'source',true
    )
    on conflict(route_id) do update set
      status=excluded.status,
      segments=excluded.segments,
      checked_at=excluded.checked_at,
      continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,
      official=true;

    update public.hiking_routes
      set trace_available=true,
          published=true,
          distance_km=round(v_length_km::numeric,2),
          route_type=v_item->>'type'
      where id=v_route.id;
  end loop;
end
$curate$;
